def _get_annotation(node):
    """Get the type annotation for a node, if available.

    Checks for:
    1. Direct annotations on the assignment (AnnAssign)
    2. Annotations from function arguments when the assigned value
       is a function parameter

    Returns the inferred annotation type or None.
